package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StdDateFormat.parseAsISO8601.
 * Since the method is protected, we use a subclass to expose it for testing.
 */
public class StdDateFormat_parseAsISO8601_TriageGen2Test {

    private TestableStdDateFormat dateFormat;

    // Subclass to allow testing of the protected method
    private static class TestableStdDateFormat extends StdDateFormat {
        public TestableStdDateFormat() {
            super();
        }

        public TestableStdDateFormat(TimeZone tz, Locale loc) {
            super(tz, loc);
        }

        @Override
        public Date parseAsISO8601(String dateStr, ParsePosition pos) {
            return super.parseAsISO8601(dateStr, pos);
        }

        // Mocking hasTimeZone behavior via public parse if needed, 
        // but since we are testing the actual logic, we rely on real behavior.
    }

    @Before
    public void setUp() {
        dateFormat = new TestableStdDateFormat();
    }

    @Test
    public void testParsePlainDate() throws Exception {
        // len <= 10 and ends with digit
        String dateStr = "2023-05-21";
        Date result = dateFormat.parseAsISO8601(dateStr, new ParsePosition(0));
        assertNotNull(result);

        Calendar cal = Calendar.getInstance();
        cal.setTime(result);
        assertEquals(2023, cal.get(Calendar.YEAR));
        assertEquals(Calendar.MAY, cal.get(Calendar.MONTH));
        assertEquals(21, cal.get(Calendar.DAY_OF_MONTH));
    }

    @Test
    public void testParseZuluWithMissingMilliseconds() throws Exception {
        // Ends with 'Z', length check for ':' at len-4
        // "2023-05-21T10:00:00Z" -> len=20, len-4 is ':'
        String dateStr = "2023-05-21T10:00:00Z";
        Date result = dateFormat.parseAsISO8601(dateStr, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseZuluWithMilliseconds() throws Exception {
        // Ends with 'Z', len-4 is not ':'
        String dateStr = "2023-05-21T10:00:00.123Z";
        Date result = dateFormat.parseAsISO8601(dateStr, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseWithTimeZoneOffsetAndColon() throws Exception {
        // hasTimeZone = true, contains ':', removes colon
        // Example: 2023-05-21T10:00:00+05:00
        // The logic: c = dateStr.charAt(len-3) which is ':'
        String dateStr = "2023-05-21T10:00:00+05:00";
        Date result = dateFormat.parseAsISO8601(dateStr, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseWithTimeZoneOffsetMissingMinutes() throws Exception {
        // hasTimeZone = true, c is '+' or '-', appends '00'
        // Example: 2023-05-21T10:00:00+05
        String dateStr = "2023-05-21T10:00:00+05";
        Date result = dateFormat.parseAsISO8601(dateStr, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseWithTimeZoneOffsetMissingMilliseconds() throws Exception {
        // hasTimeZone = true, len-9 is a digit (triggers .000 insertion)
        // "2023-05-21T10:00:00+05:00" -> len=25. len-9 = 16. charAt(16) is '0' (from seconds)
        String dateStr = "2023-05-21T10:00:00+05:00";
        Date result = dateFormat.parseAsISO8601(dateStr, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseNoTimeZoneIndicator() throws Exception {
        // hasTimeZone = false, appends .000 and Z
        // Example: 2023-05-21T10:00:00
        String dateStr = "2023-05-21T10:00:00";
        Date result = dateFormat.parseAsISO8601(dateStr, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseNoTimeZoneIndicatorShortTime() throws Exception {
        // hasTimeZone = false, timeLen <= 8
        // Example: 2023-05-21T10:00
        String dateStr = "2023-05-21T10:00";
        Date result = dateFormat.parseAsISO8601(dateStr, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testWithSpecificTimeZoneAndLocale() throws Exception {
        TimeZone tz = TimeZone.getTimeZone("GMT");
        Locale loc = Locale.US;
        dateFormat = new TestableStdDateFormat(tz, loc);

        String dateStr = "2023-05-21T10:00:00Z";
        Date result = dateFormat.parseAsISO8601(dateStr, new ParsePosition(0));

        Calendar cal = Calendar.getInstance(tz, loc);
        cal.setTime(result);
        assertEquals(2023, cal.get(Calendar.YEAR));
        assertEquals(10, cal.get(Calendar.HOUR_OF_DAY));
    }

    @Test
    public void testParsePositionFailure() {
        // Test that ParsePosition is actually used/respected
        String dateStr = "not-a-date";
        ParsePosition pos = new ParsePosition(0);
        Date result = dateFormat.parseAsISO8601(dateStr, pos);

        // Since the logic tries to parse via df.parse, if it's invalid, 
        // it usually returns null or sets error index in pos.
        // Given the complexity of the string manipulation, we check if pos is updated.
        assertNull(result);
        assertTrue(pos.getErrorIndex() >= 0);
    }
}
